/// The build target's errno numbers, one constant per name `errno!` knows (0 on
/// targets `errno!` doesn't support, where it is a compile error anyway). Not
/// public API.
pub mod table {
    use super::{TABLE, number_of};

    /// Whether `errno!` has a numbering for this target.
    pub const SUPPORTED: bool = !TABLE.is_empty();

    macro_rules! errnos {
        ($($name:ident)*) => {
            $(
                pub const $name: i32 = match number_of(TABLE, stringify!($name)) {
                    Some(n) => n,
                    None => 0,
                };
            )*
        };
    }

    errnos! {
        EPERM ENOENT ESRCH EINTR EIO ENXIO E2BIG ENOEXEC
        EBADF ECHILD EAGAIN ENOMEM EACCES EFAULT ENOTBLK EBUSY
        EEXIST EXDEV ENODEV ENOTDIR EISDIR EINVAL ENFILE EMFILE
        ENOTTY ETXTBSY EFBIG ENOSPC ESPIPE EROFS EMLINK EPIPE
        EDOM ERANGE EDEADLK EDEADLOCK ENAMETOOLONG ENOLCK ENOSYS ENOTEMPTY
        ELOOP ENOMSG EIDRM ECHRNG EL2NSYNC EL3HLT EL3RST ELNRNG
        EUNATCH ENOCSI EL2HLT EBADE EBADR EXFULL ENOANO EBADRQC
        EBADSLT EBFONT ENOSTR ENODATA ETIME ENOSR ENONET ENOPKG
        EREMOTE ENOLINK EADV ESRMNT ECOMM EPROTO EMULTIHOP EDOTDOT
        EBADMSG EOVERFLOW ENOTUNIQ EBADFD EREMCHG ELIBACC ELIBBAD ELIBSCN
        ELIBMAX ELIBEXEC EILSEQ ERESTART ESTRPIPE EUSERS ENOTSOCK EDESTADDRREQ
        EMSGSIZE EPROTOTYPE ENOPROTOOPT EPROTONOSUPPORT ESOCKTNOSUPPORT EOPNOTSUPP EPFNOSUPPORT EAFNOSUPPORT
        EADDRINUSE EADDRNOTAVAIL ENETDOWN ENETUNREACH ENETRESET ECONNABORTED ECONNRESET ENOBUFS
        EISCONN ENOTCONN ESHUTDOWN ETOOMANYREFS ETIMEDOUT ECONNREFUSED EHOSTDOWN EHOSTUNREACH
        EALREADY EINPROGRESS ESTALE EUCLEAN ENOTNAM ENAVAIL EISNAM EREMOTEIO
        EDQUOT ENOMEDIUM EMEDIUMTYPE ECANCELED ENOKEY EKEYEXPIRED EKEYREVOKED EKEYREJECTED
        EOWNERDEAD ENOTRECOVERABLE ERFKILL EHWPOISON
    }
}

/// A Linux errno value with the build target's number, usually written with
/// [`errno!`](crate::linux::errno).
///
/// `Eq`, `Ord` and `Hash` go by number, and `Display` writes the canonical name
/// (`EAGAIN` for `errno!("EWOULDBLOCK")`).
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Errno(i32);

impl Errno {
    /// The errno with this number on the build target, or `None` if it has none.
    pub const fn from_number(number: i32) -> Option<Self> {
        match name_of(TABLE, number) {
            Some(_) => Some(Self(number)),
            None => None,
        }
    }

    #[doc(hidden)]
    pub const fn __new_unchecked(number: i32) -> Self {
        Self(number)
    }

    /// The errno's number on the build target.
    pub const fn number(self) -> i32 {
        self.0
    }

    /// The errno's canonical name, like `"ENOENT"`.
    pub const fn name(self) -> &'static str {
        match name_of(TABLE, self.0) {
            Some(name) => name,
            None => "E?",
        }
    }
}

impl fmt::Display for Errno {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.name())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn errno_tables() {
        let tables: [&Table; 4] = [&GENERIC, &POWERPC, &MIPS, &SPARC];
        for (family, table) in tables.iter().enumerate() {
            // Every number has one canonical name, and every name one number.
            for &(name, number) in table.iter() {
                assert_eq!(
                    number_of(table, name),
                    Some(number),
                    "{name} in table {family}"
                );
                let canonical = name_of(table, number).unwrap();
                assert!(
                    canonical == name || name == "EDEADLOCK",
                    "{name} in table {family}"
                );
            }
            assert_eq!(number_of(table, "EPERM"), Some(1));
        }
        assert_eq!(number_of(&GENERIC, "EDEADLOCK"), Some(35));
        assert_eq!(number_of(&POWERPC, "EDEADLOCK"), Some(58));
        assert_eq!(number_of(&MIPS, "EDQUOT"), Some(1133));
        assert_eq!(name_of(&GENERIC, 35), Some("EDEADLK"));
    }
}
